// Hard cap: refuse anything past iteration 5 so an Agent+auto-deploy
// loop can never run (and bill) unbounded.
const loop = parseInt(msg.req && msg.req.query && msg.req.query.loop, 10) || 1;
if (loop > 5) {
    msg.payload = 'Loop limit (5) reached - stopped.';
    return [msg, null];
}
const ack = RED.util.cloneMessage(msg);
ack.payload = 'Accepted iteration ' + loop + ' of 5.';
msg.loop = loop;
msg.payload = 'Self-feedback iteration ' + loop + ' of 5: in the flow "LLM feedback target", update ONLY the comment node named "feedback_log" so its text records this iteration number and ONE short improvement idea for the self-feedback flow. Do not add, remove, rewire, or modify any other node.';
return [ack, msg];

// Single source of the loop URL. Override the base with the
// LLM_LOOP_BASE env var when Node-RED is not on 127.0.0.1:1880.
const next = (msg.loop || 0) + 1;
if (next > 5) {
    msg.payload = 'Completed 5 iterations - loop finished.';
    return [null, msg];
}
const base = env.get('LLM_LOOP_BASE') || 'http://127.0.0.1:1880';
msg.url = base + '/llm-loop?loop=' + next;
msg.method = 'GET';
msg.payload = '';
return [msg, null];
